import json, os

REPO = "/work/fastapi"
SRC_EXT = {'.py','.js','.ts','.tsx','.go','.rs','.java','.c','.cc','.cpp','.h','.hpp'}
SKIP_DIRS = {'.git','node_modules','vendor','target','build','dist','__pycache__','.claude','examples'}

def reason_for(relpath):
    top = relpath.split('/')[0]
    if top == 'tests':
        return "test"
    if top == 'docs_src':
        return "documentation example snippet embedded in the docs site"
    if top == 'docs':
        return "docs site asset (JS behind the documentation site, not the library)"
    if top == 'scripts':
        return "CI/dev-tooling script (release, docs build, translation, lint helpers)"
    return "out of scope: " + top

all_src = []
for dirpath, dirnames, filenames in os.walk(REPO):
    dirnames[:] = [d for d in dirnames if d not in SKIP_DIRS and d != '.git']
    rel_dir = os.path.relpath(dirpath, REPO)
    parts = set(rel_dir.split(os.sep)) if rel_dir != '.' else set()
    if parts & SKIP_DIRS:
        continue
    for fn in filenames:
        ext = os.path.splitext(fn)[1]
        if ext in SRC_EXT:
            rel = os.path.normpath(os.path.join(rel_dir, fn)) if rel_dir != '.' else fn
            all_src.append(rel.replace(os.sep, '/'))

fastapi_pkg = sorted(p for p in all_src if p.startswith('fastapi/'))
others = sorted(p for p in all_src if not p.startswith('fastapi/'))

print("fastapi package files:", len(fastapi_pkg))
print("other src-ext files:", len(others))

excluded = [{"path": p, "reason": reason_for(p)} for p in others]

with open('/tmp/claude-0/-work-fastapi/0952cbec-4a03-5a81-b7e7-96d9d04827c0/scratchpad/excluded.json', 'w') as f:
    json.dump(excluded, f, indent=2)

with open('/tmp/claude-0/-work-fastapi/0952cbec-4a03-5a81-b7e7-96d9d04827c0/scratchpad/fastapi_pkg_files.json', 'w') as f:
    json.dump(fastapi_pkg, f, indent=2)
